function escapeXml(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function nl(d){ var s='\n'; for(var i=0;i<d;i++) s+='  '; return s; }
function tokenize(xml){
  var toks=[]; var i=0;
  while(i<xml.length){
    if(xml[i]==='<'){
      if(xml.substr(i,4)==='<!--'){ var e=xml.indexOf('-->',i); if(e<0){ toks.push({type:'comment',text:xml.slice(i)}); i=xml.length; break; } toks.push({type:'comment',text:xml.slice(i,e+3)}); i=e+3; continue; }
      var e=xml.indexOf('>',i); if(e<0){ toks.push({type:'text',text:xml.slice(i)}); break; }
      var tag=xml.slice(i,e+1);
      if(tag[1]==='/') toks.push({type:'close',text:tag});
      else if(tag[tag.length-2]==='/') toks.push({type:'self',text:tag});
      else toks.push({type:'open',text:tag});
      i=e+1; continue;
    } else {
      var e=xml.indexOf('<',i); if(e<0) e=xml.length;
      var txt=xml.slice(i,e);
      if(txt.trim()!=='') toks.push({type:'text',text:txt});
      i=e; continue;
    }
  }
  return toks;
}
function formatXml(xml){
  xml=String(xml); var out=''; var depth=0;
  var toks=tokenize(xml);
  for(var t=0;t<toks.length;t++){
    var tk=toks[t];
    if(tk.type==='comment'){ out+=nl(depth)+tk.text; }
    else if(tk.type==='open'){ out+=nl(depth)+tk.text; depth++; }
    else if(tk.type==='self'){ out+=nl(depth)+tk.text; }
    else if(tk.type==='close'){ depth=Math.max(0,depth-1); out+=nl(depth)+tk.text; }
    else if(tk.type==='text'){ var v=tk.text.replace(/\s+/g,' ').trim(); if(v) out+=nl(depth)+escapeXml(v); }
  }
  return out.replace(/^\n+/,'');
}
function validateXml(xml){
  var stack=[]; var toks=tokenize(xml);
  for(var t=0;t<toks.length;t++){
    var tk=toks[t];
    if(tk.type==='open'){
      var name=tk.text.match(/^<\s*([a-zA-Z_][\w.-]*)/);
      if(!name) return {ok:false,msg:'非法标签: '+tk.text.slice(0,20)};
      stack.push(name[1]);
    } else if(tk.type==='close'){
      var name=tk.text.match(/^\s*<\/\s*([a-zA-Z_][\w.-]*)/);
      if(!name) return {ok:false,msg:'非法闭合标签'};
      if(!stack.length || stack[stack.length-1]!==name[1]) return {ok:false,msg:'标签不匹配: '+name[1]};
      stack.pop();
    }
  }
  if(stack.length) return {ok:false,msg:'未闭合标签: '+stack.join(',')};
  return {ok:true,msg:''};
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { formatXml:formatXml, validateXml:validateXml, escapeXml:escapeXml };
}
if (typeof window !== 'undefined') {
  window.XmlForgePure = { formatXml:formatXml, validateXml:validateXml, escapeXml:escapeXml };
}
